ev=np.linalg.eigvalsh(h)
Dq_unit=((ev[3]+ev[4])/2-(ev[0]+ev[1]+ev[2])/3)/10.0
h1=h/Dq_unit   # one-electron LF matrix in units of Dq (eg-t2g=10)
print("t2g,eg check:",np.round(np.linalg.eigvalsh(h1),6))
