        M[a,c,q+k]=np.sum(np.conj(phi_m[a])*np.conj(yk)*phi_m[c]*W)
        N[a,c,q+k]=np.sum(np.conj(phi_m[a])*yk*phi_m[c]*W)
  ang[k]=(M,N)
