      sgn*=(-1)**bin(st&((1<<p)-1)).count('1'); st|=(1<<p)
    else:
      if not occ: return None,0
      sgn*=(-1)**bin(st&((1<<p)-1)).count('1'); st&=~(1<<p)
  return st,sgn
n=len(states)
def opmat(terms):
  # terms: list of (coef, ops) ; returns matrix
  H=np.zeros((n,n),complex)
  for i,st in enumerate(states):
    for c,ops in terms:
      s2,sg=apply(ops,st)
      if s2 is not None: H[idx[s2],i]+=c*sg
  return H
