def ee_terms(k):
  t=[]
  T=Vk[k]
  for p,q,r,s in itertools.product(range(NSO),repeat=4):
    if abs(T[p,q,r,s])>1e-10:
      t.append((0.5*T[p,q,r,s],[('a',r),('a',s),('c',q),('c',p)]))
  return t
