Sz=np.array([0.5*(sum((st>>(2*m))&1 for m in range(5))-sum((st>>(2*m+1))&1 for m in range(5))) for st in states])
S2=Sp.T@Sp+np.diag(Sz*(Sz+1))
Nd=null_space((S2-0.75*np.eye(n)).real)
